package com.nexus.access.backend.auth;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.OffsetDateTime; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.nexus.access.backend.exception.InvalidCredentialsException; import com.nexus.access.backend.user.User;
@Service @Transactional public class RefreshTokenService { private final RefreshTokenRepository repository; private final long expiration; private final SecureRandom random=new SecureRandom(); public RefreshTokenService(RefreshTokenRepository r,@Value("${jwt.refresh-expiration}") long e){repository=r;expiration=e;} public String issue(User user){byte[] bytes=new byte[48];random.nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);RefreshToken entity=new RefreshToken();entity.setUser(user);entity.setTokenHash(hash(token));entity.setExpiresAt(OffsetDateTime.now().plusSeconds(expiration));repository.save(entity);return token;} public User consume(String raw){RefreshToken token=repository.findByTokenHash(hash(raw)).orElseThrow(InvalidCredentialsException::new);if(token.getRevokedAt()!=null||token.getExpiresAt().isBefore(OffsetDateTime.now()))throw new InvalidCredentialsException();token.setRevokedAt(OffsetDateTime.now());return token.getUser();} public void revoke(String raw){repository.findByTokenHash(hash(raw)).ifPresent(t->t.setRevokedAt(OffsetDateTime.now()));} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
